                   "Nur gewöhnliche 64-Bit-PC-Hardware (amd64) wird unterstützt; dieser Node ist '%s'."
msg pve_unknown    "Onbekende Proxmox-versie: %s" "Unknown Proxmox version: %s" "Unbekannte Proxmox-Version: %s"
